mapper.select:
select
a.robot_alarm_id,
a.alarm_name,
a.robot_id,
a.station_id,
a.alarm_type,
a.alarm_level,
a.alarm_info,
a.alarm_time,
a.deal_type,
a.deal_info,
a.deal_person_id,
a.deal_time,
a.position_station_num,
a.position_offset,
a.alarm_state,
a.create_time,
a.end_time
from t_robot_alarm a
where 1 = 1
 and a.robot_alarm_id = #{robotAlarmId, jdbcType=BIGINT}
 and a.alarm_name = #{alarmName, jdbcType=VARCHAR}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.station_id = #{stationId, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=INTEGER}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.alarm_info = #{alarmInfo, jdbcType=VARCHAR}
 and a.alarm_time = #{alarmTime, jdbcType=TIMESTAMP}
 and a.deal_type = #{dealType, jdbcType=INTEGER}
 and a.deal_info = #{dealInfo, jdbcType=VARCHAR}
 and a.deal_person_id = #{dealPersonId, jdbcType=VARCHAR}
 and a.deal_time = #{dealTime, jdbcType=TIMESTAMP}
 and a.position_station_num = #{positionStationNum, jdbcType=VARCHAR}
 and a.position_offset = #{positionOffset, jdbcType=VARCHAR}
 and a.alarm_state = #{alarmState, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.end_time = #{endTime, jdbcType=TIMESTAMP}

